if (ocOpenBtn) { e.preventDefault(); NoryxUI.offcanvas.open(ocOpenBtn.getAttribute("data-nx-offcanvas")); return; }
const ocCloseBtn = target.closest("[data-nx-dismiss='offcanvas']");
if (ocCloseBtn) { NoryxUI.offcanvas.close(ocCloseBtn.closest(".nx-offcanvas")); return; }
